Technique ARIA17: Using grouping roles to identify related form controls - Example 2: Identifying radio groups
This example demonstrates use role=radiogroup . Note also that the radio buttons are custom controls with role=radio . One may optionally employ CSS to place a border around groups of such fields to visually reinforce the group relationship. The CSS properties are available below the form. < h3 > Set Alerts for your Account </ h3 > < div role = "radiogroup" aria-labelledby = "alert1" > < p id = "alert1" > Send an alert when balance exceeds $3,000 </ p > < div > < span role = "radio" aria-checked = "false" aria-labelledby = "a1r1" name = "a1radio" > </ span > < span id = "a1r1" > Yes </ span > </ div > < div > < span role = "radio" aria-checked = "false" aria-labelledby = "a1r2" name = "a1radio" > </ span > < span id = "a1r2" > No </ span > </ div > </ div > < div role = "radiogroup" aria-checked = "false" aria-labelledby = "alert2" > < p id = "alert2" > Send an alert when a charge exceeds $250 </ p > < div > < span role = "radio" aria-checked = "false" aria-labelledby = "a2r1" name = "a2radio" > </ span > < span id = "a2r1" > Yes </ span > </ div > < div > < span role = "radio" aria-checked = "false" aria-labelledby = "a2r2" name = "a2radio" > </ span > < span id = "a2r2" > No </ span > </ div > </ div > < input type = "submit" value = "Continue" name = "continue_btn" > Related CSS Style Definition to place a border around the group of fields: div [role=radiogroup] { border : black thin solid;
} Working example: using grouping roles to identify related form controls . Note

Technique ARIA19: Using ARIA role=alert or Live Regions to Identify Errors - Example 1: Injecting error messages into a container with role=alert already present in the DOM
JavaScript is used to test if the inputs are empty on submit and inject error messages into the live region containers if so. Each time a new submit is attempted the previous error messages are removed from the container and new error messages injected. // Get the form element const form = document . getElementById ( 'signup' ); // Listen for when the form is submitted form. addEventListener ( 'submit' , function ( event ) { // Stop the form from actually submitting (so we can check it first) event. preventDefault (); // Get references to the input fields const firstNameInput = document . getElementById ( 'first' ); const lastNameInput = document . getElementById ( 'last' ); const emailInput = document . getElementById ( 'email' ); // Get the element where we'll show error messages const errorsContainer = document . getElementById ( 'errors' ); // Create an empty array to collect error messages const errorMessages = []; // Check if first name is empty if (firstNameInput. value === '' ) {
  errorMessages. push ( '<li>Please enter your first name.</li>' );
} // Check if last name is empty if (lastNameInput. value === '' ) {
  errorMessages. push ( '<li>Please enter your last name.</li>' );
} // Check if email is empty if (emailInput. value === '' ) {
  errorMessages. push ( '<li>Please enter your email address.</li>' );
} // Clear the errors container first // (This helps screen readers notice when new content appears) errorsContainer. innerHTML = '' ; // Wait 500 milliseconds, then show the errors setTimeout ( function ( ) { // If there are any errors, wrap them in a list and display them if (errorMessages. length > 0 ) {
    errorsContainer. innerHTML = '<ul>' + errorMessages. join ( '' ) + '</ul>' ;
  }
}, 500 );
});

Technique ARIA2: Identifying a required field with the aria-required property - Example 3: Required fields are indicated by a red border around the fields and a star icon rendered via CSS using ::after
This example uses custom radio buttons with role=radio . The CSS properties are available below the form. < form > < label data-required = "true" for = "acctnum" > Account Number </ label > < input aria-required = "true" id = "acctnum" type = "text" > < p data-required = "true" id = "radio_label" > Please send an alert when balance exceeds $3,000. </ p > < ul aria-required = "true" aria-labelledby = "radio_label" role = "radiogroup" > < li aria-checked = "false" id = "rb1" role = "radio" tabindex = "0" > Yes </ li > < li aria-checked = "false" id = "rb2" role = "radio" tabindex = "-1" > No </ li > </ ul > </ form > Related CSS style definition for this example: [aria-required=true] { border : red thin solid;
} [data-required=true] ::after { content : url ( '/iconStar.gif' );
}

Technique ARIA21: Using aria-invalid to Indicate An Error Field - Example 1: Using aria-invalid on required fields
The aria-invalid attribute is used on required fields that are empty when the form is submitted. A message above the form tells the user that there are form fields that need to be completed. < form name = "signup" id = "signup" method = "post" action = "" > < p id = "errors" aria-live = "assertive" > </ p > < div > < label for = "first" > First Name (required) </ label > < input aria-invalid = "false" autocomplete = "given-name" id = "first" name = "first" type = "text" > </ div > < div > < label for = "last" > Last Name (required) </ label > < input aria-invalid = "false" autocomplete = "family-name" id = "last" name = "last" type = "text" > </ div > < div > < label for = "email" > Email (required) </ label > < input aria-invalid = "false" autocomplete = "email" id = "email" name = "email" type = "text" > </ div > < div > < button id = "button" type = "submit" > Sign Up </ button > </ div > </ form > label .failed { background : #CE0000 ; color : #fff ;
} These are the two JavaScript functions that set the aria-invalid="true" attribute and then create the validation error message: const requiredFields = [ 'first' , 'last' , 'email' ]; let errorCount = 0 ;

requiredFields. forEach ( fieldId => { const field = document . getElementById (fieldId); if (field. value . trim () === '' ) {
    field. setAttribute ( 'aria-invalid' , 'true' ); document . querySelector ( `label[for=' ${fieldId} ']` ). classList . add ( 'failed' );
    errorCount++;
  }
}); if (errorCount > 0 ) {
  errText. textContent = `Please complete all ${errorCount} required ${errorCount === 1 ? 'field' : 'fields' } and retry` ;
} Working example: Using aria-invalid on required fields .

Technique ARIA21: Using aria-invalid to Indicate An Error Field - Features
Adds an aria-invalid="true" attribute on a form field if the entered data is missing or not in the expected format: The PIN contains fewer than 4 characters; The email address doesn't meet the required format; The last name must contain at least two letters; The policy start date is before today's date. The PIN contains fewer than 4 characters; The email address doesn't meet the required format; The last name must contain at least two letters; The policy start date is before today's date. Displays an error message which is programmatically connected to the relevant form field using the aria-describedby attribute. < div class = "control" > < label for = "pin4" > PIN * (4 digits) </ label > < input id = "pin4" name = "pin4" pattern = "\d{4}" size = "4" type = "text" aria-describedby = "pin4-errormsg" aria-invalid = "true" class = "error" > < span class = "errtext" id = "pin4-errormsg" > Error: PIN is required </ span > </ div > .error { border : #CE0000 thin solid;
} .errtext { background : #EEEEFF url ( 'error-icon.svg' ) no-repeat right 0.25em center; color : #CE0000 ; display :block; margin-bottom : 1em ; max-width : fit-content; padding : . 25em 1.6em . 25em . 25em ;
} JavaScript is needed to add aria-invalid , aria-describedby , and class attributes as well as appending the error text. This function is the relevant part of the larger validation script: function addFieldError ( field, message ) { const errId = field. id + '-errormsg' ; const errDiv = document . createElement ( 'div' );
  errDiv. className = 'errtext' ;
  errDiv. id = errId;
  errDiv. textContent = message;

  field. parentNode . appendChild (errDiv);
  field. setAttribute ( 'aria-describedby' , errId);
  field. setAttribute ( 'aria-invalid' , 'true' );
  field. classList . add ( 'error' );
} Working example: Identifying errors in data format .

Technique ARIA5: Using WAI-ARIA state and property attributes to expose the state of a user interface component - Example 1: A toggle button
A widget with role button acts as a toggle button when it implements the attribute aria-pressed . When aria-pressed is true, the button is in a "pressed" state. When aria-pressed is false, it is not pressed. If the attribute is not present, the button is a simple command button. The following snippet from the ARIA Authoring Practices Guide (APG) examples for button shows WAI-ARIA mark-up for a toggle button to mute/unmute audio: < a tabindex = "0" role = "button" id = "toggle" aria-pressed = "false" > Mute
  ... </ a > The a element has a role="button" and an aria-pressed attribute. The following excerpt from the Javascript for this example updates the value of the aria-pressed attribute: /**
* Toggles the toggle button's state between *pressed* and *not pressed*.
*
* @param { HTMLElement } button */ function toggleButtonState ( button ) { var isAriaPressed = button. getAttribute ( 'aria-pressed' ) === 'true' ;
  button. setAttribute ( 'aria-pressed' , isAriaPressed ? 'false' : 'true' );
  ...
}

Technique ARIA5: Using WAI-ARIA state and property attributes to expose the state of a user interface component - Example 2: A slider
A widget with role slider lets a user select a value from within a given range. The slider represents the current value and the range of possible values via the size of the slider and the position of the handle. These properties of the slider are represented by the attributes aria-valuemin , aria-valuemax , and aria-valuenow . The following snippet from the ARIA Authoring Practices Guide (APG) color viewer slider example shows WAI-ARIA mark-up for one of the sliders: < div id = "id-red" class = "color-slider-label" > Red </ div > < div class = "color-slider red" role = "slider" tabindex = "0" aria-valuemin = "0" aria-valuenow = "128" aria-valuemax = "255" aria-labelledby = "id-red" > ... </ div > The following excerpt from the Javascript for this example updates the value of the aria-valuenow attribute when the value of the slider handle is changed: moveSliderTo ( slider, value ) {
  ...
  slider. sliderNode . setAttribute ( 'aria-valuenow' , value);
  ...
}

Technique SCR14: Using scripts to make nonessential alerts optional - The JavaScript
< script > document . addEventListener ( "DOMContentLoaded" , function ( e ) { const stockBox = document . querySelector ( "#stock-box" ); const stockMovement = document . querySelector ( "#stock-movement" ); const onBtn = document . querySelector ( "#live-on" ); const offBtn = document . querySelector ( "#live-off" ); const stocks = new Array ( "stock went down" , "stock stayed the same" , "stock went up" ); let loopCount = 0 ;	

  onBtn. addEventListener ( "click" , modifyLive, false );
  offBtn. addEventListener ( "click" , modifyLive, false ); function modifyLive ( e ){ let elm = e. currentTarget ; let liveState = elm. getAttribute ( "id" ); if (liveState === "live-off" ){
      stockBox. setAttribute ( "aria-live" , "off" );
      onBtn. setAttribute ( "aria-pressed" , "false" );
      offBtn. setAttribute ( "aria-pressed" , "true" );
    } else {
      stockBox. setAttribute ( "aria-live" , "assertive" );
      onBtn. setAttribute ( "aria-pressed" , "true" );
      offBtn. setAttribute ( "aria-pressed" , "false" );      
    }
  } setInterval ( () => { if (loopCount > 2 ){
      loopCount = 0 ;
    }
    stockMovement. innerHTML = stocks[loopCount];
      loopCount++;
    }, 10000 )
  }); </ script >

Technique SCR16: Providing a script that warns the user a time limit is about to expire - Example 1
A page of stock market quotes uses script to refresh the page every five minutes in order to ensure the latest statistics remain available. 20 seconds before the five minute period expires, a confirm dialog appears asking if the user needs more time before the page refreshes. This allows the user to be aware of the impending refresh and to avoid it if desired. <!doctype html > < html lang = "en" > < head > < meta charset = "utf-8" > < title > Stock Market Quotes </ title > < script > function timeControl ( ) { // set timer for 4 min 40 sec, then ask user to confirm. setTimeout ( 'userCheck()' , 280000 );
     } function userCheck ( ) { // set page refresh for 20 sec var id= setTimeout ( 'pageReload()' , 20000 ); // If user selects "OK" the timer is reset // else the page will refresh from the server. if ( confirm ( "This page is set to refresh in 20 seconds. Would you like more time?" ))
       { clearTimeout (id); timeControl ();
       }
     } function pageReload ( ) { window . location . reload ( true );
     } timeControl (); </ script > </ head > < body > < h1 > Stock Market Quotes </ h1 > ... </ body > </ html >

Technique SCR18: Providing client-side validation and alert - Example 2: Checking multiple controls when the user submits the form
The following sample shows multiple controls in a form. The form element uses the onsubmit attribute which creates an event handler to execute the validation script when the user attempts to submit the form. If the validation is successful, the event returns true and the form submission proceeds; if the validation finds errors, it displays an error message and returns false to cancel the submit attempt so the user can fix the problems. Note This example demonstrates an alert for simplicity. A more helpful notification to the user would be to highlight the controls with problems and add information to the page about the nature of the errors and how to navigate to the controls that require data fixes. Although this example uses an onsubmit attribute on the form element for brevity, normal practice is to create a submit event listener when the page is loaded. Script code: function validate ( ) { // initialize error message var msg = "" ; //validate name var pattern = /^[a-zA-Z\s]+$/ ; var el = document . getElementById ( "name" ); if (!pattern. test (el. value )) {
    msg += "Name can only have letters and spaces. " ;
  } // validate number var pattern = /^[\d\-+\.\s]+$/ ; var el = document . getElementById ( "tel" ); if (!pattern. test (el. value )) {
    msg += "Telephone number can only have digits and separators. " ;
  } if (msg != "" ) { alert (msg); return false ;
  } else { return true ;
  } Form code: < form action = "multiple-controls.html" onsubmit = "return validate()" > < div > < label for = "name" > Name: </ label > < input autocomplete = "name" id = "name" name = "name" type = "text" > </ div > < div > < label for = "tel" > Telephone number: </ label > < input autocomplete = "tel" id = "tel" name = "tel" type = "tel" > </ div > < div > < input type = "submit" > </ div > </ form > This is demonstrated in the working example of checking multiple controls when the user submits the form .

Technique SCR2: Using redundant keyboard and mouse event handlers - Example 1
<!doctype html > < html lang = "en" > < head > < meta charset = "utf-8" > < title > Changing Image Source in a Device Independent Manner </ title > < script > /* This function will change the image src of an image element.
        * param imgId - the id of the image object to change
        * param isOver - true when mouse is over or object has focus,
         false when mouse move out or focus is lost
       */ function updateImage ( imgId, isOver ) { var theImage = document . getElementById (imgId); if (theImage != null ) { if (isOver) {
           theImage. setAttribute ( "src" , "yellowplus.gif" );
         } else {
           theImage. setAttribute ( "src" , "greyplus.gif" );
         }
       }
     } </ script > </ head > < body > < p > Mouse over or tab to the links below and see the image change. </ p > < a href = "https://www.w3.org/WAI/" onmouseover = "updateImage('wai', true);" onfocus = "updateImage('wai', true);" onmouseout = "updateImage('wai',false);" onblur = "updateImage('wai',false);" > < img alt = "" id = "wai" src = "greyplus.gif" > W3C Web Accessibility Initiative </ a > &amp; < a href = "https://www.w3.org/International/" onmouseover = "updateImage('i18n', true);" onfocus = "updateImage('i18n',true);" onmouseout = "updateImage('i18n',false);" onblur = "updateImage('i18n',false);" > < img alt = "" id = "i18n" src = "greyplus.gif" > W3C Internationalization </ a > </ body > </ html >

Technique SCR22: Using scripts to control blinking and stop it in five seconds or less - Example 1
This example uses JavaScript to control blinking of some HTML and XHTML content. JavaScript creates the blinking effect by changing the visibility status of the content. It controls the start of the effect and stops it within five seconds. ... < div id = "blink1" class = "highlight" > New item! </ div > < script > // blink "on" state function show ( ) { if ( document . getElementById ){ document . getElementById ( "blink1" ). style . visibility = "visible" ;
  }
} // blink "off" state function hide ( ) { if ( document . getElementById ){ document . getElementById ( "blink1" ). style . visibility = "hidden" ;
  }
} // toggle "on" and "off" states every 450 ms to achieve a blink effect // end after 4500 ms (less than five seconds) for ( let i= 900 ; i < 4500 ; i=i+ 900 ) { setTimeout ( "hide()" ,i); setTimeout ( "show()" ,i+ 450 );
} </ script > ... Working example of this code: Using script to control blinking .

Technique SCR24: Using progressive enhancement to open new windows on user request - Script:
window . onload = addHandlers; function addHandlers ( ){ var objAnchor = document . getElementById ( 'newwin' ); if (objAnchor){
    objAnchor. firstChild . data = objAnchor. firstChild . data + ' (opens in a new window)' ;
    objAnchor. onclick = function ( event ){ return launchWindow ( this , event);} // UAAG requires that user agents handle events in a device-independent manner // but only some browsers do this, so add keyboard event to be sure objAnchor. onkeypress = function ( event ){ return launchWindow ( this , event);}
  }
} function launchWindow ( objAnchor, objEvent )
   { var iKeyCode, bSuccess= false ; // If the event is from a keyboard, we only want to open the // new window if the user requested the link (return or space) if (objEvent && objEvent. type == 'keypress' )
     { if (objEvent. keyCode )
         iKeyCode = objEvent. keyCode ; else if (objEvent. which )
         iKeyCode = objEvent. which ; // If not carriage return or space, return true so that the user agent // continues to process the action if (iKeyCode != 13 && iKeyCode != 32 ) return true ;
     }

     bSuccess = window . open (objAnchor. href ); // If the window did not open, allow the browser to continue the default // action of opening in the same window if (!bSuccess) return true ; // The window was opened, so stop the browser processing further return false ;
   }

Technique SCR26: Inserting dynamic content into the Document Object Model immediately following its trigger element - Example 1
This example creates a menu when a link is clicked and inserts it after the link. The onclick event of the link is used to call the ShowHide script, passing in an id for the new menu as a parameter. < button aria-expanded = "false" type = "button" onclick = "ShowHide('foo',this)" > Toggle </ button > The ShowHide script creates a div containing the new menu, and inserts a link into it. The last line is the core of the script. It finds the parent of the element that triggered the script, and appends the div it created as a new child to it. This causes the new div to be in the DOM after the menu. When the user hits tab, the focus will go to the first focusable item in the menu, the link we created. function ShowHide ( id,src ){ var el = document . getElementById (id); if (!el){
    el = document . createElement ( "div" );
    el. id = id; var link = document . createElement ( "a" );
    link. href = "/laptops" ;
    link. appendChild ( document . createTextNode ( "Laptops" ));
    el. appendChild (link);
    src. parentElement . appendChild (el);
    src. setAttribute ( "aria-controls" , id);
    src. setAttribute ( "aria-expanded" , "true" );
   } else if (el && src. getAttribute ( "aria-expanded" ) === "false" ){
     el. style . display = 'block' ;
     src. setAttribute ( "aria-expanded" , "true" );
   } else {
     el. style . display = 'none' ;
     src. setAttribute ( "aria-expanded" , "false" );    
   }   
} CSS is used to make the div and link look like a menu.

Technique SCR27: Reordering page sections using the Document Object Model - Example 1
Then, after checking the reorder direction, we try to grab the node to swap. If we find one, we then call swapNode() to swap our two modules, and PositionElement() to move the absolutely-positioned menu along with the module, and then set focus back on the menu item which launched the whole thing. function MoveNode ( evt,dir ){ HarmonizeEvent (evt);
  evt. preventDefault (); var src = evt. target ; var menu = src. parentNode . parentNode ; var module = menu. parentNode . parentNode . parentNode ; var menuLink = module . getElementsByTagName ( "a" )[ 0 ]; var swap = null ; switch (dir){ case 'up' : {
      swap = module . previousSibling ; while (swap && swap. nodeType != 1 ){
        swap = swap. previousSibling ;
      } break ;
    } case 'down' : {
      swap = module . nextSibling ; while (swap && swap. nodeType != 1 ){
        swap = swap. nextSibling ;
      } break ;
    }
  } if (swap && swap. tagName == node. tagName ){ module . swapNode (swap); PositionElement (menu,menuLink, false , true );
  }
  src. focus ();
} The CSS for the node swap is not much different than that of our previous tree samples, with some size and color adjustment for the modules and the small menu. ul #swapper {
  list-item-style:none; margin : 0px ; padding : 0px ;
} ul #swapper li { border : 1px solid black; height : 5em ; list-style :none; margin : 1em ; padding : 0 ; width : 15em ;
} ul #swapper li a { color :white; font-size : 90% ; text-decoration :none;
} ul #swapper li div .module_header { padding : 0 0.2em ; text-align :right ;
} ul #swapper li div .module_body { padding : 0.2em ;
} ul #swapper ul .menu { background-color : #eeeeee ; border : 1px solid gray; display :none; height :auto; list-style :none; margin : 0 ; padding : 0 ; position :absolute; text-align :left ;
} ul #swapper ul .menu li { border :none; font-weight :normal; height :auto; margin : 0 ; text-align :left ; width : 5em ;
} ul #swapper ul .menu li a { color :black; display :block; padding : 0 0.1em ; text-decoration :none; width : 100% ;
}

Technique SCR28: Using an expandable and collapsible menu to bypass block of content - Example 1: Toggling a table of contents
The table of contents for a set of web pages is repeated near the beginning of each web page. A button at the beginning of the table of contents lets the user remove or restore it on the page. ... < script > let tocToggle = document . querySelector ( ".toc-toggle" ); let toc = document . querySelector ( "#toc" );
tocToggle. addEventListener ( "click" , toggle, false ); function toggle ( e ){ let elm = e. currentTarget ; if (elm. getAttribute ( "aria-expanded" ) === "false" ){
    elm. setAttribute ( "aria-expanded" , "true" );
  } else {
    elm. setAttribute ( "aria-expanded" , "false" );
  }
} </ script > ... < button aria-controls = "toc" aria-expanded = "true" class = "toc-toggle" type = "button" > Toggle Table Of Contents </ button > < nav aria-labelledby = "toc-header" id = "toc" > < h2 id = "toc-header" > Table of Contents </ h2 > < ul > < li > < a href = "#sec1" > Section 1 </ a > </ li > < li > < a href = "#sec2" > Section 2 </ a > </ li > < li > < a href = "#sec3" > Section 3 </ a > </ li > < li > < a href = "#sec4" > Section 4 </ a > </ li > </ ul > </ nav > ... Working example of this code: Toggle table of contents with a button .

Technique SCR29: Adding keyboard-accessible actions to static HTML elements - Example 1: Adding a JavaScript action to a div element
The div element on the page is given a unique id attribute and a tabindex attribute with value 0 . A script uses the Document Object Model (DOM) to find the div element by its id and add the onclick handler and the onkeyup handler. The onkeyup handler will invoke the action when the Enter key is pressed. Note that the div element must be loaded into the DOM before it can be found and modified. This is usually accomplished by calling the script from the onload event of the body element. The script to add the event handlers will only execute if the user agent supports and has JavaScript enabled. < script > // this is the function to perform the action. This simple example toggles a message. function doSomething ( event ) { var msg= document . getElementById ( "message" );
  msg. style . display = msg. style . display == "none" ?

Technique SCR29: Adding keyboard-accessible actions to static HTML elements - Example 1: Adding a JavaScript action to a div element
< script > // this is the function to perform the action. This simple example toggles a message. function doSomething ( event ) { var msg= document . getElementById ( "message" );
  msg. style . display = msg. style . display == "none" ? "" : "none" ; //return false from the function to make certain // that the href of the link does not get invoked return false ;
  } // this is the function to perform the action when the Enter key has been pressed. function doSomethingOnEnter ( event ) { var key = 0 ; // Determine the key pressed, depending on whether window.event // or the event object is in use if ( window . event ) {
      key = window . event . keyCode ;
    } else if (event) {
      key = event. keyCode ;
    } // Was the Enter or Space key pressed? if (key == 13 || key == 32 ) { return doSomething (event);
    } // The event has not been handled, so return true return true ;
  } // This setUpActions() function must be called to set the onclick and onkeyup // event handlers onto the existing div element. // This function must be called after the div element with id="active" // has been loaded into the DOM. // In this example the setUpActions() function is called from the onload event // for the body element. function setUpActions ( ) { // get the div object var active= document . getElementById ( "active" ); // assign the onclick handler to the object. active. onclick =doSomething; // assign the onkeyup handler to the object. active. onkeyup =doSomethingOnEnter;
} </ script > < body onload = "setUpActions();" > < p > Here is the link to modify with a javascript action: </ p > < div > < span id = "active" role = "button" tabindex = "0" > Do Something </ span > </ div > < div aria-live = "polite" > < div id = "message" > Hello, world! </ div > </ div > </ body > Working example of this code: Creating Divs with Actions using JavaScript .

Technique SCR30: Using scripts to change the link text - Example 1
The link class is used to determine which additional text to add. When the "Expand Links" link is activated, each link on the page is tested to see whether additional text should be added. ... < script > var expanded = false ; var linkContext = { "hist" : " version of The History of the Web" , "cook" : " version of Cooking for Nerds" }; function doExpand ( ) { var links = document . links ; for ( var i= 0 ; i<links. length ; i++) { var link = links[i]; var cn = link. className ; if (linkContext[cn]) {
        span = link. appendChild ( document . createElement ( "span" ));
        span. setAttribute ( "class" , "linkexpansion" );
        span. appendChild ( document . createTextNode (linkContext[cn]));
      }
    }
    objUpdate = document . getElementById ( 'expand' ); if (objUpdate) {
      objUpdate. childNodes [ 0 ]. nodeValue = "Collapse links" ;
    }
    expanded = true ;
  } function doCollapse ( ) {
    objUpdate = document . getElementById ( 'expand' ); var spans = document . getElementsByTagName ( "span" ); var span; // go backwards through the set as removing from the front changes indices // and messes up the process for (i = spans. length - 1 ; i >= 0 ; i--) {
      span = spans[i]; if (span. getAttribute ( "class" ) == "linkexpansion" )
        span. parentNode . removeChild (span);
      } if (objUpdate) {
      objUpdate. childNodes [ 0 ]. nodeValue = "Expand links" ;
    }
    expanded = false ;
  } function toggle ( ) { if (expanded) doCollapse (); else doExpand ();
  } </ script > ... < h1 > Books for download </ h1 > < p > < button id = "expand" onclick = "toggle(); type=" button "> Expand Links </ button > </ p > < ul > < li > The History of the Web: < a href = "history.docx" class = "hist" > Word </ a > , < a href = "history.pdf" class = "hist" > PDF </ a > , < a href = "history.html" class = "hist" > HTML </ a > </ li > < li > Cooking for Nerds: < a href = "history.docx" class = "cook" > Word </ a > , < a href = "history.pdf" class = "cook" > PDF </ a > , < a href = "history.html" class = "cook" > HTML </ a > </ li > </ ul > ...

